from rest_framework import routers
from django.urls import path, include
from project.views import ProjectViewSet


# Define the application namespace for URL reversing
app_name = "project"

# Create a DRF router for automatic URL routing
router = routers.DefaultRouter()

# Register the ProjectViewSet with an empty prefix to handle all project-related endpoints
router.register("", ProjectViewSet, basename="project")

# Define the URL patterns for the project app
# This includes all the routes automatically generated by the router
urlpatterns = [path("", include(router.urls))]
